//! Where the lab's files live. Every path is derived from an identifier
//! generated by the server: no client-supplied name ever reaches the
//! file system.

use std::path::{Path, PathBuf};

use crate::ids::{DatasetId, JobId, ModelId};

/// Directories of the lab (the server and the workers see the same ones).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LabPaths {
    /// One directory of `CBDS` files per dataset.
    pub datasets: PathBuf,
    /// One `<id>.nnue` file per model.
    pub models: PathBuf,
    /// One directory per training job: checkpoints.
    pub runs: PathBuf,
}

impl LabPaths {
    /// `datasets/`, `models/` and `runs/` under `root`.
    #[must_use]
    pub fn under(root: &Path) -> Self {
        Self {
            datasets: root.join("datasets"),
            models: root.join("models"),
            runs: root.join("runs"),
        }
    }

    /// Directory of a dataset's files.
    #[must_use]
    pub fn dataset_dir(&self, id: DatasetId) -> PathBuf {
        self.datasets.join(id.to_string())
    }

    /// Files of a dataset, in order.
    #[must_use]
    pub fn dataset_files(&self, id: DatasetId) -> Vec<PathBuf> {
        chess_dataset::dataset_files(&self.dataset_dir(id), None)
    }

    /// Network file of a model.
    #[must_use]
    pub fn model_file(&self, id: ModelId) -> PathBuf {
        self.models.join(format!("{id}.nnue"))
    }

    /// Working directory of a training job (checkpoints).
    #[must_use]
    pub fn run_dir(&self, id: JobId) -> PathBuf {
        self.runs.join(id.to_string())
    }
}
